r.morphs = Object.keys(mesh.morphTargetDictionary || {});
r.morph_max_mm = {};
const weigh = (m, w) => skinned.forEach((o) => { const k = o.morphTargetDictionary?.[m]; if (k !== undefined) o.morphTargetInfluences[k] = w; });
for (const m of r.morphs) {
  weigh(m, 1);
  r.morph_max_mm[m] = +(maxMove(rest, positions(skinned)) * 1000).toFixed(2);
  weigh(m, 0);
}
